/**
 * Photo helpers. The list of photos and their authors lives in photos.data.ts;
 * dimensions, available widths and blur placeholders are generated by `npm run photos`
 * into photos.generated.json. See photos.data.ts for how to replace a photo.
 */
import { photoSources, type PhotoKey } from "./photos.data.ts";
import generated from "./photos.generated.json";

export type { PhotoKey };

export type Photo = {
  key: PhotoKey;
  width: number;
  height: number;
  widths: number[];
  blur: string;
  author: string;
  /** Source page for credits (Pexels photos only). */
  source?: string;
};

type Gen = Record<string, { width: number; height: number; widths: number[]; blur: string }>;

export const photos = Object.fromEntries(
  (Object.keys(photoSources) as PhotoKey[]).map((key) => {
    const src = photoSources[key] as { pexels?: number; author: string };
    const gen = (generated as Gen)[key];
    if (!gen) throw new Error(`Photo "${key}" has not been generated – run: npm run photos`);
    const photo: Photo = {
      key,
      ...gen,
      author: src.author,
      source: src.pexels ? `https://www.pexels.com/photo/${src.pexels}/` : undefined,
    };
    return [key, photo];
  }),
) as Record<PhotoKey, Photo>;

const file = (key: string, w: number) => `${import.meta.env.BASE_URL}images/${key}-${w}.webp`;

/** URL of the variant closest to (and not smaller than) the requested width. */
export function photoUrl(p: Photo, w = 960): string {
  const best = p.widths.find((x) => x >= w) ?? p.widths[p.widths.length - 1];
  return file(p.key, best);
}

export function photoSrcSet(p: Photo): string {
  return p.widths.map((w) => `${file(p.key, w)} ${w}w`).join(", ");
}
